import React, { useState } from 'react';
import styled from 'styled-components';
import Picker from 'emoji-picker-react';

export default function ChatInput({ handleSendMsg }) {
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [msg, setMsg] = useState('');

  const handleEmojiPickerHandler = () => {
    setShowEmojiPicker(!showEmojiPicker);
  };
  const handleEmojiClick = (event, emoji) => {
    let message = msg;
    message += emoji.emoji;
    setMsg(message);
  };
  const sendChat = (event) => {
    event.preventDefault();
    if (msg.length > 0) {
      handleSendMsg(msg);
      setMsg('');
    }
  };

  return (
    <Container>
      {/* <div className="button_container"> */}
        <div className="emoji">
          <ion-icon
            name="happy-outline"
            onClick={handleEmojiPickerHandler}
          ></ion-icon>
          {/* <span className="icon">emoji-icon</span> */}
          {showEmojiPicker && <Picker onEmojiClick={handleEmojiClick} />}
        </div>
        <ion-icon name="attach-outline"></ion-icon>
      {/* </div> */}
      <form className="input_container" onSubmit={(e) => sendChat(e)}>
        <div id="input">
          <div
            title="Type your message"
            class="input__div"
            role="textbox"
            contenteditable="true"
            placeholder="messages..."
            value={msg}
            onChange={(e) => setMsg(e.target.value)}
          ></div>
        </div>

        {/* <input type="text" /> */}
        <button className="submit">
          <ion-icon name="paper-plane-outline"></ion-icon>
        </button>
      </form>
    </Container>
  );
}

const Container = styled.div`
  background: hsl(208 22% 15%);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 15px;

  ion-icon {
    font-size: 1.8rem;
    color: hsl(208 22% 73% / 0.49);
    font-weight: 700;
    cursor: pointer;
    margin-bottom: 10px;
  }
  ion-icon:nth-child(1) {
    margin-right: 15px;
  }
  ion-icon:nth-child(2) {
    transform: rotate(-20deg);
  }
  #input {
    width: 90%;
    border-radius: 8px;
    margin: 5px 10px;
    overflow: hidden;
    padding: 9px 12px 11px;
    background: hsl(208 22% 21%);
    color: hsl(208 22% 83%);
    word-break: break-all;
    word-wrap: break-word;
    overflow-wrap: break-word;
    height: auto;
  }

  .input__div {
    outline: none;
    border: none;
    height: 100%;
    width: 100%;
    max-height: 100px;
    overflow-y: auto;
  }

  .input__div::-webkit-scrollbar-thumb {
    border-radius: 0;
  }
`;
